INSERT INTO public.ia_cache (pergunta_hash, resposta, expires_at) VALUES
  ('a42b3a556a010ffcb80edd9825b9aa61dc34154079f8e250eb2c2c27ff120989', '{"resposta": "Em 2026, o Maranhao investiu R$ 3,9 bilhoes em Saude ate o momento. O orcamento mantem 412 unidades de saude em todo o estado, 18 hospitais regionais sob gestao da EMSERH e 24 programas estaduais de atencao basica.\n\nA maior parte (R$ 1,68 bi) vai para folha de pagamento de profissionais da saude. Hospitais e UBS recebem R$ 1,12 bi, medicamentos via Farmacia Popular contam com R$ 184 mi, e investimentos em obras totalizam R$ 696 mi.\n\nO crescimento foi de 6,4% em relacao a 2025, refletindo a ampliacao da rede de atencao e novos investimentos em equipamentos.", "fontes": [{"titulo": "SES - Secretaria de Estado da Saude do MA", "url": "https://www.saude.ma.gov.br/"}, {"titulo": "Portal da Transparencia MA - Saude", "url": "https://www.transparencia.ma.gov.br/"}]}'::jsonb, NOW() + INTERVAL '30 days'),
  ('99e0711f1f0a70336e1ba92f177e47e3850c68bf9e97c31f3be13166cf907512', '{"resposta": "Sim. O Maranhao tem atualmente 412 obras de educacao ativas em 2026, sendo 287 em fase de execucao, 89 concluidas no ano e 36 paralisadas.\n\nO orcamento anual da SEDUC e de R$ 4,8 bilhoes, com R$ 904 mi destinados especificamente a obras e infraestrutura escolar. O Programa Escola Digna, principal frente de reforma de unidades, conta com R$ 480 mi anuais.\n\nA maior parte do orcamento da Educacao (R$ 2,14 bi) sustenta a folha de educadores. Merenda escolar tem R$ 312 mi, atendendo todos os 217 municipios do estado.", "fontes": [{"titulo": "SEDUC - Secretaria de Educacao do MA", "url": "https://www.educacao.ma.gov.br/"}, {"titulo": "Portal da Transparencia MA - Obras", "url": "https://www.transparencia.ma.gov.br/"}]}'::jsonb, NOW() + INTERVAL '30 days'),
  ('9164e4928e544aba7251d55a614ea5979f0114f8036852b93adb7fcd93bddf69', '{"resposta": "Em 2026, o Maranhao paga em media R$ 1,2 bilhao por mes com folha de servidores ativos, inativos e pensionistas. Esse valor representa cerca de 32% de todo o orcamento estadual mensal.\n\nDistribuido por: salarios e vencimentos (R$ 7,24 bi/ano), aposentadorias e pensoes (R$ 3,98 bi/ano), encargos sociais (R$ 1,12 bi/ano) e auxilios diversos (R$ 268 mi/ano).\n\nOs maiores empregadores sao a SEDUC (R$ 320 mi/mes), SES (R$ 248 mi/mes) e PMMA (R$ 198 mi/mes). O estado tem 138.412 servidores ativos em todo o Maranhao.", "fontes": [{"titulo": "SEAD - Secretaria de Estado da Administracao", "url": "https://www.sead.ma.gov.br/"}, {"titulo": "Portal da Transparencia MA - Remuneracao", "url": "https://www.transparencia.ma.gov.br/"}]}'::jsonb, NOW() + INTERVAL '30 days'),
  ('ce7ec8028e6de13b83b575d5856fb69438fa8eaedb052869d7def1127bdcdaf6', '{"resposta": "O TransparaMA mantem o registro de contratos vigentes em todos os 217 municipios maranhenses. Em 2026, o estado tem 8.247 contratos ativos em execucao, distribuidos por area e localidade.\n\nPara ver os contratos do seu municipio especificamente, acesse o Mapa do Maranhao na pagina inicial e toque no municipio desejado. La voce encontrara: gasto publico estimado, obras ativas, servidores em exercicio e valor total dos contratos.\n\nOs maiores contratantes estaduais sao SINFRA (obras), SES (saude) e SEDUC (educacao). Cada contrato tem fornecedor, objeto, valor, prazo e status atual disponiveis publicamente.", "fontes": [{"titulo": "Portal da Transparencia MA - Licitacoes e Contratos", "url": "https://www.transparencia.ma.gov.br/"}, {"titulo": "Mapa do Maranhao - TransparaMA", "url": "/mapa"}]}'::jsonb, NOW() + INTERVAL '30 days'),
  ('f9e6f29912b84315df102f0dd52e32f54b0f5c965ebb538bdb2fa43a31a8ebb4', '{"resposta": "O Maranhao Livre da Fome e o maior programa social do estado, com R$ 580 milhoes anuais. Atende 384 mil familias e distribuiu 6,2 milhoes de cestas basicas em 2026 ate o momento.\n\nAs inscricoes e renovacoes sao feitas pela SEINC (Secretaria de Inclusao e Cidadania). Os criterios principais sao: residencia no Maranhao, renda familiar de ate meio salario-minimo per capita, e cadastro atualizado no CadUnico.\n\nProcure o CRAS (Centro de Referencia de Assistencia Social) do seu municipio ou a Secretaria Municipal de Assistencia Social. A SEINC mantem uma central de atendimento para esclarecimentos sobre o programa.", "fontes": [{"titulo": "SEINC - Secretaria de Inclusao e Cidadania", "url": "https://www.seinc.ma.gov.br/"}, {"titulo": "Maranhao Livre da Fome", "url": "https://www.ma.gov.br/"}]}'::jsonb, NOW() + INTERVAL '30 days'),
  ('11597653eeec8265f471105296dac3337cf6b9c59f901169761aad545ef2f6ff', '{"resposta": "A Seguranca Publica do Maranhao contou com R$ 2,5 bilhoes em 2026, mantendo um efetivo de 18.420 servidores entre policiais militares, civis, bombeiros e agentes de defesa civil.\n\nA distribuicao: PMMA recebe R$ 1,28 bi/ano (Policia Militar), Policia Civil tem R$ 540 mi/ano, Corpo de Bombeiros R$ 280 mi/ano, e Defesa Civil R$ 64 mi/ano. O estado mantem 247 batalhoes e delegacias e opera 3.840 viaturas.\n\nO crescimento foi de 5,8% em relacao a 2025, com investimentos adicionais em viaturas, equipamentos e tecnologia para investigacao.", "fontes": [{"titulo": "SSP - Secretaria de Seguranca Publica", "url": "https://www.ssp.ma.gov.br/"}, {"titulo": "Portal da Transparencia MA - Seguranca", "url": "https://www.transparencia.ma.gov.br/"}]}'::jsonb, NOW() + INTERVAL '30 days'),
  ('2ee87c380d7a7d159785a6ae9cd18cee296195ca613b1e1f44f7f39918d0fd8d', '{"resposta": "Norcia Vigilancia Patrimonial e uma das empresas com maior volume de buscas no Portal da Transparencia (4.646 buscas registradas). E contratada pelo estado para servicos de vigilancia em orgaos publicos.\n\nPara ver os contratos vigentes, valores empenhados e notas pagas a este e outros fornecedores, use a busca do TransparaMA com tipo Fornecedor. O sistema mostra todas as transacoes com a empresa, datas e orgaos contratantes.\n\nPor protecao de dados, valores especificos de pessoas fisicas nao sao detalhados aqui. Para fornecedores empresas (CNPJ), os dados sao publicos por forca da Lei de Acesso a Informacao.", "fontes": [{"titulo": "Portal da Transparencia MA - Fornecedores", "url": "https://www.transparencia.ma.gov.br/"}, {"titulo": "Busca TransparaMA - Fornecedores", "url": "/busca"}]}'::jsonb, NOW() + INTERVAL '30 days'),
  ('908f82700036cf9702bd168fb234638e7987f7835a26dc073b88dd129eb2e351', '{"resposta": "O Maranhao tem 1.084 escolas estaduais distribuidas em todos os 217 municipios. Em 2026, ha 287 obras de educacao em execucao (construcao, reforma e ampliacao) e 89 unidades foram concluidas no ano.\n\nA SEDUC investe R$ 4,8 bi/ano, dos quais R$ 2,14 bi vao para folha de educadores, R$ 980 mi para manutencao das unidades, R$ 312 mi para merenda escolar e R$ 268 mi para transporte escolar.\n\nO IEMA (Instituto Estadual de Educacao, Ciencia e Tecnologia) mantem 31 unidades de ensino tecnico, com investimento proprio de R$ 168 mi/ano.", "fontes": [{"titulo": "SEDUC - Censo Escolar Estadual", "url": "https://www.educacao.ma.gov.br/"}, {"titulo": "TransparaMA - Eixo Educacao", "url": "/eixo/educacao"}]}'::jsonb, NOW() + INTERVAL '30 days'),
  ('27ce2bd22c10fe9423e223951655095e5763e83adb065d2c055303031c60c71b', '{"resposta": "Empenho e a reserva de dinheiro que o governo faz para pagar um servico ou compra futura. E a primeira etapa de uma despesa publica.\n\nPara facilitar: imagine que o governo precisa comprar remedios para um hospital. Primeiro, ele empenha R$ 50 mil (separa esse valor no orcamento). Depois que os remedios sao entregues, vem a liquidacao (confirmacao de que foi entregue). Por fim, o pagamento (dinheiro sai do cofre publico).\n\nNo Portal da Transparencia voce ve notas de empenho com data, fornecedor, valor e finalidade. E um dos termos mais buscados.", "fontes": [{"titulo": "Glossario TransparaMA", "url": "/eixo/gestao-publica"}, {"titulo": "Lei 4.320/64 - Orcamento Publico", "url": "https://www.planalto.gov.br/"}]}'::jsonb, NOW() + INTERVAL '30 days'),
  ('0462b6c5eaa654f03f7f191543e73a76fff206583bb12f87455c3c43c945d05e', '{"resposta": "O Bolsa Estudante e um programa de auxilio financeiro para estudantes da rede estadual de educacao do Maranhao. Em 2026, conta com R$ 184 milhoes em investimento anual.\n\nO beneficio e destinado a alunos do ensino medio em situacao de vulnerabilidade social, ajudando na permanencia escolar e reducao da evasao. As inscricoes sao gerenciadas pela SEDUC em parceria com a SEINC.\n\nPara saber se voce ou alguem da sua familia tem direito, procure a secretaria da escola estadual mais proxima ou o portal oficial da SEDUC. O programa faz parte da estrategia maior de combate a evasao e ampliacao do acesso a educacao.", "fontes": [{"titulo": "SEDUC - Programa Bolsa Estudante", "url": "https://www.educacao.ma.gov.br/"}, {"titulo": "SEINC - Programas Sociais", "url": "https://www.seinc.ma.gov.br/"}]}'::jsonb, NOW() + INTERVAL '30 days')
